const products=[
{id:'wide',name:'Jeans Wide Leg',type:'Calças',wash:'Azul médio',image:'wide.webp',description:'Proposta de modelagem ampla para compor o catálogo. Foto e características ilustrativas: substituir pelo produto real antes da abertura da loja online.'},
{id:'reta',name:'Jeans Reta',type:'Calças',wash:'Índigo escuro',image:'reta.webp',description:'Proposta de modelagem reta em lavagem escura. Foto e características ilustrativas: disponibilidade, composição e medidas ainda serão cadastradas.'},
{id:'short',name:'Short Jeans',type:'Shorts',wash:'Azul claro',image:'short.webp',description:'Proposta de short com barra dobrada. Foto e características ilustrativas: este item não representa uma oferta ou estoque confirmado.'}
];
const main=document.querySelector('main'),dialog=document.querySelector('#cart-dialog');let cart=[];try{cart=JSON.parse(localStorage.getItem('ms-prototype-cart-v1')||'[]').filter(x=>products.some(p=>p.id===x.id)&&typeof x.size==='string'&&/^(PP|P|M|G|GG|XG|XGG|[3-6][0-9])$/.test(x.size)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99)}catch{cart=[]}let filter='Todos',query='',sort='default',selectedSize='',quantity=1,toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(kind)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v11M7 5l10 4"/>',person:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-4a7 7 0 0 1 14 0v4"/>',truck:'<path d="M2 5h12v12H2ZM14 10h4l4 4v3h-8"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',card:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20M6 15h4"/>'})[kind]}</svg>`;
const card=p=>`<article><a class="product-image" href="#produto/${p.id}"><img src="${productImage(p.image)}" alt="${esc(p.name)}, ${esc(p.wash)}, imagem ilustrativa" loading="lazy"><span class="product-badge">MODELO ILUSTRATIVO</span></a><div class="product-info"><div class="meta">${esc(p.type.toUpperCase())} / ${esc(p.wash.toUpperCase())}</div><h3><a href="#produto/${p.id}">${esc(p.name)}</a></h3><div class="price">Preço a definir</div><p class="stock-summary">${stockSummary(p)}</p><div class="product-bottom"><div class="swatch" aria-label="${esc(p.wash)}"><span style="background:${p.id==='reta'?'#253d56':p.id==='short'?'#9bb9cc':'#577f9d'}"></span></div><a href="#produto/${p.id}">Escolher tamanhos ↗</a></div></div></article>`;
const faqs=[['Posso comprar com CPF?','Sim. Não precisa ter CNPJ para comprar na MS. O pedido mínimo é de 6 peças.'],['As 6 peças podem ser variadas?','Sim. Você pode montar seu pedido com peças variadas. Consulte modelos e tamanhos disponíveis com a equipe.'],['Como funciona a entrega?','A MS faz entrega. Frete, prazo e região atendida são confirmados com a equipe de acordo com o destino.'],['Quais são as formas de pagamento?','Pix e cartão. Parcelamento em até 12x, com a taxa por conta do cliente. Consulte o total e as parcelas antes de confirmar.']];
const faq=()=>faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">JEANS NO ATACADO / LAJEADO, RS</div><h1>Sua próxima<br>vitrine<br><span>começa aqui.</span></h1><p>Jeans de altíssima qualidade para abastecer sua loja. Perto de você, do jeito que seu negócio precisa.</p><a class="btn" href="#catalogo">EXPLORAR CATÁLOGO <span>↗</span></a></div><div class="hero-photo"><img src="/assets/hero.webp" alt="Jeans em uma mesa de madeira com luz natural"><div class="hero-label"><strong>06</strong><div>PEÇAS PARA COMEÇAR<small>Monte seu pedido com modelos variados.</small></div></div><span class="photo-note">Imagem ilustrativa</span></div></section><section class="benefits" aria-label="Condições do atacado"><div>${icon('box')}<div><b>A partir de 6 peças</b><small>Seu pedido pode ser variado.</small></div></div><div>${icon('person')}<div><b>CPF ou CNPJ</b><small>Atacado também para quem começa.</small></div></div><div>${icon('truck')}<div><b>Entrega disponível</b><small>Consulte frete e prazo.</small></div></div><div>${icon('card')}<div><b>Pix ou até 12x no cartão</b><small>Taxa por conta do cliente.</small></div></div></section><section class="wrap section"><div class="section-head"><div><div class="eyebrow">ENCONTRE SEU PRÓXIMO PEDIDO</div><h2>Jeans que fazem parte<br>da sua vitrine.</h2></div><a class="text-link" href="#catalogo">Ver todo o catálogo ↗</a></div><div class="grid">${products.map(card).join('')}</div><p class="demo-note">Prévia do e-commerce: produtos e imagens ilustrativos. Preços, grade e estoque serão definidos com a MS.</p></section><section class="wholesale" id="atacado"><div><div class="eyebrow">COMPRAR NO ATACADO É SIMPLES</div><h2>Você escolhe.<br>A gente abastece.</h2><a href="#como-comprar" class="btn dark">CONHEÇA O ATACADO ↗</a></div><div class="steps"><div class="step"><span>01</span><div><h3>Escolha os seus jeans</h3><p>Explore os modelos e consulte os tamanhos disponíveis.</p></div></div><div class="step"><span>02</span><div><h3>Monte seu pedido com 6 peças</h3><p>Pode misturar modelos. Compras com CPF ou CNPJ.</p></div></div><div class="step"><span>03</span><div><h3>Combine os próximos passos</h3><p>Confira pagamento, frete e prazo com a nossa equipe.</p></div></div></div></section><section class="wrap section faq-layout"><div><div class="eyebrow">SEM COMPLICAÇÃO</div><h2>Primeira compra?<br>Chega mais.</h2><p>As respostas para começar seu próximo pedido com tranquilidade.</p><a class="text-link" href="#atendimento">Tirar uma dúvida com a MS ↗</a></div><div>${faq()}</div></section><section class="store-banner"><div><div class="eyebrow">SEU FORNECEDOR ESTÁ AQUI</div><h2>De Lajeado para a sua loja.</h2><p>Conheça as peças de perto e converse com a nossa equipe.</p></div><a class="btn outline" href="#loja">CONHECER A LOJA ↗</a></section>`}
function catalog(){return `<div class="wrap section"><div class="catalog-heading"><div class="crumb"><a href="#inicio">Início</a> / Catálogo</div><h1>Seu próximo pedido.</h1><p>Escolha os modelos. Misture as peças. Comece com 6.</p></div><div class="catalog-controls"><div class="tabs" aria-label="Categoria">${['Todos','Calças','Shorts'].map(t=>`<button data-filter="${t}" class="${filter===t?'active':''}" aria-pressed="${filter===t}">${t}</button>`).join('')}</div><label>Ordenar <select id="sort"><option value="default">Seleção MS</option><option value="az" ${sort==='az'?'selected':''}>Nome: A–Z</option></select></label></div><p class="muted" id="result-count"></p><div id="products" class="grid"></div><p class="demo-note">Catálogo demonstrativo. Modelos, tamanhos e fotos não representam estoque confirmado. Preços a definir.</p></div>`}
function product(p){return `<div class="wrap section"><div class="crumb"><a href="#inicio">Início</a> / <a href="#catalogo">Catálogo</a> / ${esc(p.name)}</div><div class="product-page"><div class="detail-photo">${productGallery(p)}</div><div class="product-detail"><div class="eyebrow">${p.type} / MODELO DEMONSTRATIVO</div><h1>${esc(p.name)}</h1><p>${esc(p.wash)}</p><p class="price">Preço a definir</p><p class="muted">Cadastro comercial pendente · Sem venda ativa</p><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><p>${esc(p.description)}</p><span class="select-label">Selecione o tamanho</span><div class="sizes" role="group" aria-label="Tamanhos demonstrativos">${sizeChoices(p)}</div><p class="muted">Escolha o tamanho e informe quantas peças quer adicionar. Você pode misturar modelos no carrinho.</p><div class="purchase-row"><div class="quantity"><button data-qty="-1" aria-label="Diminuir quantidade" ${p.variants?.some(v=>v.quantity>0)?'':'disabled'}>−</button><input id="product-qty" aria-label="Quantidade de peças" type="number" inputmode="numeric" min="1" max="99" step="1" value="1" ${p.variants?.some(v=>v.quantity>0)?'':'disabled'}><button data-qty="1" aria-label="Aumentar quantidade" ${p.variants?.some(v=>v.quantity>0)?'':'disabled'}>+</button></div><button class="btn dark" data-add="${p.id}" ${p.variants?.some(v=>v.quantity>0)?'':'disabled'}>${p.variants?.some(v=>v.quantity>0)?'Adicionar ao carrinho':'Indisponível'}</button></div><div class="hint">O mínimo é de <b>6 peças no pedido</b>. Você pode combinar modelos e tamanhos.</div><ul class="detail-list"><li>Compra com CPF ou CNPJ.</li><li>Entrega: frete e prazo a combinar.</li><li>Até 12x no cartão, com taxa por conta do cliente.</li></ul><details><summary>Detalhes do produto</summary><p>Composição, medidas, referência e cuidados serão preenchidos a partir do cadastro real. A fotografia é ilustrativa.</p></details></div></div></div>`}
function info(type){if(type==='loja')return `<section class="info-page"><div class="eyebrow">PERTINHO DE VOCÊ</div><h1>Seu atacado.<br>Aqui em Lajeado.</h1><p>Venha conhecer os jeans de perto e montar o pedido para a sua loja.</p><div class="info-box"><h2>Encontre a MS</h2><p>Rua Fialho de Vargas, 49 · Sala 101<br>Centro · Lajeado/RS</p><p>Antes de vir, confirme o horário de atendimento com a equipe.</p></div><a class="btn" href="#atendimento">FALAR COM A EQUIPE ↗</a></section>`;if(type==='atendimento')return `<section class="info-page"><div class="eyebrow">ATENDIMENTO MS</div><h1>Vamos montar<br>seu próximo pedido?</h1><p>Conte quais peças procura e, se precisar de entrega, informe seu destino.</p><div class="contact-options"><div class="info-box"><h2>WhatsApp</h2><p>(51) 99618-0830</p><a class="btn" href="https://wa.me/5551996180830" target="_blank" rel="noopener">ABRIR WHATSAPP ↗</a><p class="muted">Abre o atendimento externo. Nenhum pedido do protótipo será enviado.</p></div><div class="info-box"><h2>Grupo de lojistas</h2><p>Peça à equipe o link para entrar no grupo da MS.</p><p class="muted">Convite do grupo ainda não conectado ao site.</p></div></div></section>`;return `<section class="info-page"><div class="eyebrow">ATACADO SEM COMPLICAÇÃO</div><h1>Seu primeiro pedido<br>começa com 6 peças.</h1><p>Para quem já tem loja e para quem está começando a revender. Você compra com CPF ou CNPJ e pode escolher peças variadas.</p>${faq()}<div class="info-box"><h2>Como montar seu pedido</h2><ol><li>Escolha os modelos e tamanhos disponíveis.</li><li>Complete o mínimo de 6 peças, podendo variar.</li><li>Confira o valor, as condições de pagamento e a entrega com a equipe.</li></ol><p class="muted">Neste protótipo você testa a seleção de peças. Pedidos e pagamentos ainda não estão ativos.</p></div><a class="btn" href="#catalogo">EXPLORAR O CATÁLOGO ↗</a></section>`}
function renderProducts(){let list=products.filter(p=>(filter==='Todos'||p.type===filter)&&(!query||(p.name+' '+p.wash).toLowerCase().includes(query.toLowerCase())));if(sort==='az')list.sort((a,b)=>a.name.localeCompare(b.name));document.querySelector('#products').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h2>Nenhum modelo encontrado.</h2><p>Tente outro termo ou limpe os filtros.</p><button class="btn" data-clear>Limpar busca e filtros</button></div>`;document.querySelector('#result-count').textContent=`${list.length} modelos ilustrativos${query?' para “'+query+'”':''}`;}
function route(){const [route,params]=(location.hash.slice(1)||'inicio').split('?');if(route==='catalogo'){const sp=new URLSearchParams(params);filter=sp.get('tipo')||'Todos';if(!['Todos','Calças','Shorts'].includes(filter))filter='Todos';query=sp.get('busca')||'';document.querySelector('#search').value=query;main.innerHTML=catalog();renderProducts()}else if(route.startsWith('produto/')){selectedSize='';quantity=1;const p=products.find(p=>p.id===route.split('/')[1]);main.innerHTML=p?product(p):'<section class="info-page"><h1>Produto não encontrado</h1><a class="btn" href="#catalogo">Voltar ao catálogo</a></section>'}else if(['loja','como-comprar','atendimento'].includes(route)){main.innerHTML=info(route)}else main.innerHTML=home();document.title=`MS Atacado — ${route==='inicio'?'Sua loja abastecida. Perto de você.':route.startsWith('produto/')?'Detalhes do produto':route==='catalogo'?'Catálogo':'Conheça a MS'}`;window.scrollTo(0,0)}
function save(){try{localStorage.setItem('ms-prototype-cart-v1',JSON.stringify(cart))}catch{}document.querySelector('#cart-count').textContent=cart.reduce((s,x)=>s+x.qty,0)}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2600)}
function renderCart(){const n=cart.reduce((s,x)=>s+x.qty,0);document.querySelector('#cart-body').innerHTML=!n?`<div class="empty"><h3>Seu próximo pedido começa aqui.</h3><p>Escolha os jeans e monte uma seleção com pelo menos 6 peças variadas.</p><button class="btn" data-shop>Explorar catálogo ↗</button></div>`:`<div class="hint">${n>=6?'Mínimo atingido. Seu pedido tem '+n+' peças.':'Faltam '+(6-n)+' peças para completar o mínimo.'}<div class="progress"><span style="width:${Math.min(n/6*100,100)}%"></span></div><small>Você pode misturar modelos e tamanhos.</small></div>${cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-line"><img src="${productImage(p.image)}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p>Tamanho ${esc(x.size)} · Preço a definir</p>${x.qty>availableStock(x.id,x.size)?'<p class="stock-warning">Estoque insuficiente: ajuste ou remova esta peça.':'<p class="muted">'+availableStock(x.id,x.size)+' disponíveis.'}</p><div class="cart-line-actions"><div class="quantity"><button data-cart-change="${i}" data-delta="-1" aria-label="Diminuir ${esc(p.name)}, tamanho ${x.size}">−</button><span>${x.qty}</span><button data-cart-change="${i}" data-delta="1" aria-label="Aumentar ${esc(p.name)}, tamanho ${x.size}">+</button></div><button class="remove" data-remove="${i}">Remover</button></div></div></div>`}).join('')}<div class="cart-summary"><div class="summary-row"><span>Quantidade</span><b>${n} peças</b></div><div class="summary-row"><span>Subtotal</span><b>A definir</b></div><div class="summary-row"><span>Frete</span><span>A consultar</span></div><button class="btn" data-review ${n<6?'disabled':''}>Revisar pedido demonstrativo ↗</button><p class="muted">Ambiente de demonstração. Você pode salvar esta seleção na sua conta. Sem pagamento ou pedido real.</p></div>`}
document.querySelector('#open-cart').onclick=()=>{renderCart();dialog.showModal()};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#search-form').onsubmit=e=>{e.preventDefault();location.hash='catalogo?busca='+encodeURIComponent(document.querySelector('#search').value.trim());if(location.hash.slice(1)==='catalogo?busca=')route()};
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;renderProducts()}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-close'))dialog.close();if(el.hasAttribute('data-shop')){dialog.close();location.hash='catalogo'}if(el.hasAttribute('data-filter')){filter=el.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)});renderProducts()}if(el.hasAttribute('data-clear')){query='';filter='Todos';location.hash='catalogo';route()}if(el.hasAttribute('data-size')){selectedSize=el.dataset.size;document.querySelectorAll('[data-size]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)})}if(el.hasAttribute('data-qty')){quantity=Math.max(1,Math.min(99,quantity+Number(el.dataset.qty)));document.querySelector('#product-qty').value=quantity}if(el.hasAttribute('data-add')){if(!selectedSize){toast('Escolha um tamanho para continuar.');document.querySelector('[data-size]:not(:disabled)')?.focus();return}const match=cart.find(x=>x.id===el.dataset.add&&x.size===selectedSize);if(match)match.qty=Math.min(99,match.qty+quantity);else cart.push({id:el.dataset.add,size:selectedSize,qty:quantity});save();toast(quantity+' peça'+(quantity===1?' adicionada':'s adicionadas')+' ao carrinho.')}if(el.hasAttribute('data-cart-change')){const i=Number(el.dataset.cartChange);cart[i].qty=Math.min(99,cart[i].qty+Number(el.dataset.delta));cart=cart.filter(x=>x.qty>0);save();renderCart()}if(el.hasAttribute('data-remove')){cart.splice(Number(el.dataset.remove),1);save();renderCart()}if(el.hasAttribute('data-review')){const n=cart.reduce((s,x)=>s+x.qty,0);if(n<6)return;document.querySelector('#cart-body').innerHTML=`<div class="success"><h3>Seleção pronta para revisão.</h3><p>Você selecionou ${n} peças. No site definitivo, esta etapa será conectada ao checkout ou ao atendimento.</p><b>Nenhum pedido foi enviado.</b></div><p class="muted">Ainda precisamos cadastrar preços, estoque, frete e meios de pagamento para ativar a loja online.</p><button class="btn" data-back-cart>Voltar ao pedido</button>`}if(el.hasAttribute('data-back-cart'))renderCart()});
window.addEventListener('hashchange',route);save();
